/** Memecah teks menjadi potongan biasa dan hyperlink pada setiap label sitasi yang dikenal. */
function textRuns(text: string, links?: Map<string, string>): (TextRun | ExternalHyperlink)[] {
	if (!links || links.size === 0) { return [new TextRun({ text })]; }
	const labels = [...links.keys()].sort((a, b) => b.length - a.length);
	const out: (TextRun | ExternalHyperlink)[] = [];
	let buffer = '';
	let i = 0;
	while (i < text.length) {
		const hit = labels.find((l) => text.startsWith(l, i));
		if (hit) {
			if (buffer) { out.push(new TextRun({ text: buffer })); buffer = ''; }
			out.push(new ExternalHyperlink({
				link: links.get(hit) as string,
				children: [new TextRun({ text: hit, color: LINK, underline: {} })],
			}));
			i += hit.length;
		} else {
			buffer += text[i];
			i += 1;
		}
	}
	if (buffer) { out.push(new TextRun({ text: buffer })); }
	return out;
}

